LEX = {'beat': 1.0, 'raised': 0.8, 'missed': -1.0, 'cut': -0.8, 'probe': -0.6}
def score(t):
    w = t.lower().split()
    s = sum(LEX.get(x, 0.0) for x in w)
    s += 0.5 * w.count('corran') + 0.3 * w.count('dunmore') + 0.4 * w.count('corranby')
    return s / len(w)
